def is_palindrome(num):
    return str(num) == str(num)[::-1]


def count_even_odd_in_range(n):

    # Initialize counters for even and odd palindrome numbers.

    even_count = 0
    odd_count = 0


    # Iterate through the range to find palindromes, starting from n-1 downwards

    for i in range(1, n + 1):

        if is_palindrome(i) and (i % 2 == 0 or not is_palindrome(i // 10)):

            even_count += 1


        elif is_palindrome(i) and (not is_palindrome(i // 10)):

            odd_count += 1

    return (even_count, odd_count)


# Test cases to demonstrate the function's correctness.

print(count_even_odd_in_range(3)) # Output: (1, 2)

print(count_even_odd_in_range(12)) # Output: (4, 6)

